#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void l2_norm_kernel(const half* input, half* output, int batch_size, int dim) {
    int batch_idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (batch_idx >= batch_size) return;

    // Shared memory for reduction
    extern __shared__ half sdata[];

    // Compute L2 norm for this batch
    half sum = __hzero();
    int offset = batch_idx * dim;

    // Reduce to compute sum of squares
    for (int i = 0; i < dim; i += blockDim.x) {
        int idx = i + threadIdx.x;
        if (idx < dim) {
            half val = input[offset + idx];
            sum = __hadd(sum, __hmul(val, val));
        }
    }

    sdata[threadIdx.x] = sum;
    __syncthreads();

