    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            sdata[threadIdx.x] = __hadd(sdata[threadIdx.x], sdata[threadIdx.x + s]);
        }
        __syncthreads();
    }

    // Compute reciprocal of norm
    half norm = sdata[0];
    half inv_norm = __hdiv(__float2half(1.0f), __hsqrt(norm));

    // Normalize the batch
    for (int i = 0; i < dim; i++) {
